// Configure public Ansatz documentation routes, navigation, and metadata.
import { defineConfig } from 'vitepress'
import { copyFileSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { join, resolve } from 'node:path'

export default defineConfig({
  // These source downloads are generated by buildEnd, after link validation.
  ignoreDeadLinks: [/^\/reliability\/(?:check_collaboration_reliability|projects)\.py$/],
  async buildEnd(config) {
    const repo = resolve(config.root, '..')
    const web = join(repo, 'agent_monitor/web')
    mkdirSync(join(config.outDir, 'reliability'), { recursive: true })
    for (const source of ['scripts/check_collaboration_reliability.py', 'agent_monitor/projects.py', 'agent_monitor/web/projects.js']) {
      copyFileSync(join(repo, source), join(config.outDir, 'reliability', source.split('/').pop()))
    }
    const base = config.site.base.replace(/\/$/, '')
    for (const name of ['run-viewer.css', 'run-viewer.js']) copyFileSync(join(web, name), join(config.outDir, name))
    mkdirSync(join(config.outDir, 'examples'), { recursive: true })
    copyFileSync(join(repo, 'agent_monitor/examples/erdos-straus.json'), join(config.outDir, 'examples/erdos-straus.json'))
    const html = readFileSync(join(web, 'run-viewer.html'), 'utf8')
      .replaceAll('__DATA_URL__', base + '/examples/erdos-straus.json')
      .replaceAll('__ASSET_BASE__', base)
      .replaceAll('__CONSOLE_URL__', '/sign-in')
    writeFileSync(join(config.outDir, 'example-run-viewer.html'), html)
  },
  title: "Ansätze",
  description: "An AI workspace for mathematical research.",
  base: '/',
  cleanUrls: true,
  appearance: true,
  head: [
    ['meta', { name: 'theme-color', content: '#ffffff' }],
    ['meta', { name: 'robots', content: 'index,follow' }],
    ['meta', { name: 'author', content: 'Richard Cai, Eric Jiang, Junyi Zhang' }]
  ],
  themeConfig: {
    siteTitle: 'Ansätze',
    nav: [
      { text: 'News', link: '/news' },
      { text: 'Quickstart', link: '/quickstart' },
      { text: 'Example run', link: '/example-run' },
      { text: 'DAG', link: '/dag' },
      { text: 'Open Problems', link: '/open-problems' },
      {
        text: 'Use as guest',
        link: '/guest',
        target: '_self'
      },
      {
        text: 'Sign in',
        link: '/sign-in',
        target: '_self'
      }
    ],
    search: {
      provider: 'local'
    },
    sidebar: [
      { text: 'Getting Started', items: [
        { text: 'Home', link: '/' },
        { text: 'News', link: '/news' },
        { text: 'Quickstart', link: '/quickstart' },
        { text: 'Example run & collaboration', link: '/example-run' },
        { text: 'Engineering & reliability', link: '/engineering' },
        { text: 'DAG · Research atlas', link: '/dag' },
        { text: 'Open Problems & Forum', link: '/open-problems' }
      ]}
    ],
    outline: [2, 3]
  }
})
